(33107, 'Leviticus 14:44', 'Leviticus', 14, 44, 'نو کاهن دې لاړ شي او هغه دې بیا معاینه کړي. که چېرې په کور کې چڼاسکه خپره شوې وي، نو دا یوه خرابوونکې چڼاسکه ده او دا کور ناپاک دی.', 'نو کاهن دې لار شی او هغه دې بیا معاینه کری. که چېرې په کور کې چناسکه خپره شوې وی، نو دا یوه خرابوونکې چناسکه ده او دا کور ناپاک دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_44.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33108, 'Leviticus 14:45', 'Leviticus', 14, 45, 'هغه کور باید وران شي او د هغه تیږې، تیرونه او ټوله خاوره باید د ښار څخه دباندې یو ناپاکه ځای ته یووړل شي.', 'هغه کور باید وران شی او د هغه تیزې، تیرونه او توله خاوره باید د شار چخه دباندې یو ناپاکه جای ته یوورل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_45.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33109, 'Leviticus 14:46', 'Leviticus', 14, 46, 'په هغه دوران کې چې کاهن هغه کور بند اعلان کړی وي، نو هرڅوک چې هغه ته ننوځي، هغه به تر ماښامه پورې ناپاک وي.', 'په هغه دوران کې چې کاهن هغه کور بند اعلان کری وی، نو هرچوک چې هغه ته ننوجی، هغه به تر ماشامه پورې ناپاک وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_46.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33110, 'Leviticus 14:47', 'Leviticus', 14, 47, 'همدارنګه هرڅوک چې په هغه کور کې خوب کوي یا خوراک کوي، باید خپل کالي ووینځي.', 'همدارنګه هرچوک چې په هغه کور کې خوب کوی یا خوراک کوی، باید خپل کالی ووینجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_47.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33111, 'Leviticus 14:48', 'Leviticus', 14, 48, 'خو که چېرې کاهن راشي او هغه معاینه کړي، نو که د کور د اخېړولو څخه وروسته چڼاسکه خپره شوې نه وي، نو هغه به کور پاک اعلان کړي، ځکه چې چڼاسکه ورکه شوې ده.', 'خو که چېرې کاهن راشی او هغه معاینه کری، نو که د کور د اخېرولو چخه وروسته چناسکه خپره شوې نه وی، نو هغه به کور پاک اعلان کری، جکه چې چناسکه ورکه شوې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_48.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33112, 'Leviticus 14:49', 'Leviticus', 14, 49, 'هغه دې د کور د پاکولو دپاره دوه مرغۍ، د سبر لرګی، سور تار او د وېلني بوټی راواخلي.', 'هغه دې د کور د پاکولو دپاره دوه مرغی، د سبر لرګی، سور تار او د وېلنی بوتی راواخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_49.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
(33113, 'Leviticus 14:50', 'Leviticus', 14, 50, 'هغه به د دغو مرغیو څخه یوه د خټو د لوښي دپاسه چې د چینې تازه اوبه په کې وي، حلاله کړي.', 'هغه به د دغو مرغیو چخه یوه د ختو د لوشی دپاسه چې د چینې تازه اوبه په کې وی، حلاله کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_50.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33114, 'Leviticus 14:51', 'Leviticus', 14, 51, 'بیا دې د سبر لرګی، د وېلني بوټی، سور تار او ژوندۍ مرغۍ راواخلي او هغه دې د مړې مرغۍ په وینه او تازه اوبو کې غوټه کړي او په کور باندې دې اووه ځلې وشیندي.', 'بیا دې د سبر لرګی، د وېلنی بوتی، سور تار او ژوندی مرغی راواخلی او هغه دې د مرې مرغی په وینه او تازه اوبو کې غوته کری او په کور باندې دې اووه جلې وشیندی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_51.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33115, 'Leviticus 14:52', 'Leviticus', 14, 52, 'په دې ډول به کاهن هغه کور د مرغۍ په وینه، تازه اوبو، ژوندۍ مرغۍ، د سبر په لرګي، د وېلني په بوټي او سور تار باندې پاک کړي.', 'په دې دول به کاهن هغه کور د مرغی په وینه، تازه اوبو، ژوندی مرغی، د سبر په لرګی، د وېلنی په بوتی او سور تار باندې پاک کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_52.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
(33116, 'Leviticus 14:53', 'Leviticus', 14, 53, 'بیا دې هغه ژوندۍ مرغۍ د ښار څخه دباندې په صحرا کې خوشې کړي. په دې ډول به هغه د کور دپاره د پاکوالي مراسم سرته ورسوي او هغه به پاک شي.»', 'بیا دې هغه ژوندی مرغی د شار چخه دباندې په صحرا کې خوشې کری. په دې دول به هغه د کور دپاره د پاکوالی مراسم سرته ورسوی او هغه به پاک شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Leviticus_14_53.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237837, 1761237837),
