(33131, 'Exodus 35:13', 'Exodus', 35, 13, 'مېز د پایو او ټول سامان سره او سپېڅلې ډوډۍ،', 'مېز د پایو او تول سامان سره او سپېچلې دودی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_35_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237837, 1761237837),
